@lru_cache(maxsize=None)
def paths(*args):return set(subprocess.check_output(['git','-C',str(ROOT),'ls-tree','-r','--name-only','-z',BASE,'--',*args],text=True).split('\0'))-{''}
@lru_cache(maxsize=None)
def adapters():
 result={}
 for p,edits in ADAPTER_EDITS.items():
  s=previous(BASE,p).decode()
  for a,b in edits:
   assert s.count(a)==1,('Changed exact adapter predecessor',p)
   s=s.replace(a,b)
  result[p]=s.encode()
 return result
@lru_cache(maxsize=None)
def expected_record():
 actual=set(subprocess.check_output(['git','-C',str(ROOT),'diff','--name-only',BASE,IMPLEMENTATION],text=True).splitlines())
 support={RECORD,'scripts/b10_release_unblock_successor.py','scripts/test_b10_release_unblock_successor.py',*ADAPTER_EDITS}
 assert support<=actual,('Changed finite successor support',support-actual)
 changed=actual-support
 changes={}
 for p in sorted(changed):
  try:before=sha(previous(BASE,p))
  except subprocess.CalledProcessError:before=None
  changes[p]={'before':before,'after':sha(previous(IMPLEMENTATION,p))}
 grants={p:[v['before']] for p,v in changes.items() if v['before']}
 # All predecessor hashes are taken from immutable historical records, never
 # from an editable working-tree manifest or an arbitrary source directory.
 for p in sorted(x for x in paths('docs/validation') if x.endswith('/compatibility.json')):
  r=json.loads(previous(BASE,p))
  for name,v in r.get('changes',{}).items():
   if name in changes:
    for d in [v.get('before'),v.get('after')]:
     if d and d not in grants.setdefault(name,[]):grants[name].append(d)
  for name,d in r.get('invariants',{}).items():
   if name in changes and d not in grants.setdefault(name,[]):grants[name].append(d)
  for name,ds in r.get('grants',{}).items():
   if name in changes:
    for d in ds:
     if d not in grants.setdefault(name,[]):grants[name].append(d)
 invariants={p:sha(previous(BASE,p)) for p in sorted(paths('src','scripts','public','releases','package.json','package-lock.json','vite.config.ts','AGENTS.md')-changed-set(ADAPTER_EDITS))}
 historical={p:sha(previous(BASE,p)) for p in sorted(paths('docs/b6-v95','docs/b6-v96','docs/b6-v97','docs/validation','releases/notes'))}
 return {'schemaVersion':1,'baseCommit':BASE,'implementationCommit':IMPLEMENTATION,'implementationSupport':sorted(support),'changes':changes,'grants':grants,'invariants':invariants,'historical':historical,'adapters':{p:{'before':sha(previous(BASE,p)),'after':sha(b)} for p,b in adapters().items()}}
def read_record(root=ROOT):
 f=root/RECORD
 if not f.exists():f=ROOT/RECORD
 r=json.loads(f.read_text());assert r==expected_record(),'Changed pinned bounded-save proof or grant';return r
def accepts(path,predecessor,root=ROOT):
 r=read_record(root);entry=r['changes'].get(path)
 return bool(entry and predecessor in r['grants'].get(path,[]) and (root/path).exists() and sha((root/path).read_bytes())==entry['after'])
def accepts_adapter(path,before,root=ROOT):
 if path not in ADAPTER_EDITS:return False
 read_record(root)
 return before==previous(BASE,path) and (root/path).exists() and (root/path).read_bytes()==adapters()[path]
def validate(root=ROOT):
 r=read_record(root)
 for p,v in r['changes'].items():assert sha((root/p).read_bytes())==v['after'],('Unrecorded bounded-save edit',p)
 for section in ['invariants','historical']:
  for p,d in r[section].items():assert sha((root/p).read_bytes())==d,('Changed preserved gameplay/source/evidence',p)
 for p,b in adapters().items():assert (root/p).read_bytes()==b,('Changed exact successor adapter',p)
 # Explicitly retain the original workload and deadlines. These checks supplement
 # the exact source hashes; they do not replace the full regression runner.
 assert 'historyFixture(150000)' in (root/'src/game/formal/persistence.test.ts').read_text()
 assert '120000' in (root/'src/game/formal/persistence.test.ts').read_text()
 assert (root/'scripts/verify-in-isolation.mjs').read_bytes()==previous(BASE,'scripts/verify-in-isolation.mjs')
 return r
if __name__=='__main__':
 r=validate()
 print(json.dumps(r) if '--boundary-record' in sys.argv else 'PASS: finite bounded-save successor; immutable gameplay, deadlines and historical evidence retained. No release approval claim.')
